pm.test("Reset returns status 200", function () {
    pm.response.to.have.status(200);
});

if (pm.response.code === 200) {
    const response = pm.response.json();

    pm.test("Firstname is restored", function () {
        pm.expect(response.firstname).to.eql("Tamara PATCH");
    });

    pm.test("Lastname is restored", function () {
        pm.expect(response.lastname).to.eql("QA");
    });

    pm.test("Totalprice is restored to 150", function () {
        pm.expect(response.totalprice).to.eql(150);
    });

    pm.test("Depositpaid is restored to true", function () {
        pm.expect(response.depositpaid).to.eql(true);
    });

    pm.test("Checkin date is restored", function () {
        pm.expect(response.bookingdates.checkin)
            .to.eql("2026-10-01");
    });

    pm.test("Checkout date is restored", function () {
        pm.expect(response.bookingdates.checkout)
            .to.eql("2026-10-05");
    });

    pm.test("Additional needs are restored", function () {
        pm.expect(response.additionalneeds).to.eql("Breakfast");
    });
}

